<!-- 模块职责：政策问答与负责人知识管理；导入需要显式确认。 -->
<script setup>
import Icon from '../components/Icon.vue'
import { ref } from 'vue'
const props = defineProps({ store: Object })
const store = props.store, s = store.state, isManager = store.manager
const input = ref(null)
function choose(event) { const file = event.target.files?.[0]; if (file) store.upload(file); event.target.value = '' }
</script>
<template><div :class="isManager ? 'two-column' : 'single-column'"><div><section class="card"><div class="card-header"><div><h2>向企业知识库提问</h2><p>回答基于检索到的政策片段，保留可核对的来源。</p></div><Icon name="book" /></div><form class="card-body" @submit.prevent="store.askPolicy"><label class="field-label" for="policy-question">政策问题</label><textarea id="policy-question" v-model="s.policyQuestion" :disabled="s.busy" rows="5" maxlength="2000" placeholder="例如：负责人拒绝或尚未审核时，可以创建正式工单吗？"></textarea><div class="composer-actions"><span>{{ s.policyQuestion.length }} / 2000</span><button class="button primary" :disabled="s.busy || !s.policyQuestion.trim()"><Icon name="search" :size="17" />检索并回答</button></div></form></section><section v-if="s.policyResult" class="card"><div class="card-header"><h2>政策回答</h2><span class="chip">{{ s.policyResult.sources?.length || 0 }} 个参考片段</span></div><div class="card-body"><p class="answer-text">{{ s.policyResult.answer }}</p><h3 class="subheading">参考来源</h3><div v-for="source in s.policyResult.sources" :key="source.citation_id" class="source-item"><span class="source-index">{{ source.citation_id }}</span><div><strong>{{ source.document_title }}</strong><p>{{ source.section }}</p><small class="selectable">{{ source.source }}</small></div></div><p v-if="!s.policyResult.sources?.length" class="muted">本次没有返回来源，请留意回答中的信息不足提示。</p></div></section></div><aside v-if="isManager"><section class="card"><div class="card-header"><h2>知识文档</h2><Icon name="file" :size="19" /></div><div class="card-body"><template v-if="isManager"><p class="muted">导入 Markdown 或可提取文本的 PDF。最大 5MB；同名文档更新为新版本。</p><input ref="input" class="sr-only" type="file" accept=".md,.pdf" aria-label="选择知识文档" @change="choose" /><button class="upload-area" :disabled="s.busy" @click="input.click()"><Icon name="cloud" :size="25" /><strong>选择文档导入</strong><small>Markdown / PDF · 最大 5MB</small></button><button class="text-button" :disabled="s.busy" @click="store.listDocuments"><Icon name="refresh" :size="15" />读取文档目录</button><div v-if="s.documentsLoaded && !s.documents.length" class="small-empty">新版本目录暂无记录。已有历史集合仍可能参与检索。</div><div v-for="document in s.documents" :key="document.collection" class="document-row"><Icon name="file" :size="18" /><span>{{ document.source }}</span><span class="tiny-dot"></span></div></template><template v-else><span class="mini-label">负责人管理</span><p class="muted">员工可检索政策。导入和查看文档管理目录需要负责人身份。</p></template></div></section><section class="aside-note"><Icon name="book" :size="22" /><h3>先有依据，再给建议</h3><p>政策回答不会执行工单操作。没有检索到可靠依据时，应明确说明信息不足。</p></section></aside></div></template>
